mapper.update:
UPDATE document_head SET revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_id=#{documentId} AND current_document_revision=#{documentRevision}
  AND revision=#{expectedDocument} AND status<>'SIGNED'

UPDATE task_head SET status='RETURNED',revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND current_revision=#{taskRevision}
  AND revision=#{expectedTask} AND status='REVIEW_PENDING'

mapper.select:
SELECT a.resource_ref FROM document_revision_return r JOIN audit_event a ON a.tenant_id=r.tenant_id
  AND a.project_id=r.project_id AND a.subject_id=r.actor_id AND r.created_by=r.actor_id
WHERE r.project_id=#{projectId} AND r.document_id=#{documentId} AND r.return_id=#{returnId}
  AND a.action='document.returned_for_revision' AND a.result='SUCCESS' AND a.request_id=#{requestId}
  AND a.created_by=r.actor_id AND a.trace_id=a.request_id AND a.reason_code IS NULL AND a.schema_version='1.0.0'
  AND a.classification=r.classification AND a.schema_manifest_sha256=#{manifest} ORDER BY a.audit_id LIMIT 2 FOR UPDATE

SELECT resource_ref FROM audit_event WHERE subject_id=#{userId} AND project_id=#{projectId}
  AND action='document.returned_for_revision' AND result='SUCCESS' AND request_id=#{requestId}
  AND created_by=#{userId} AND trace_id=request_id AND reason_code IS NULL AND schema_version='1.0.0'
  AND classification=#{classification} AND schema_manifest_sha256=#{manifest} ORDER BY audit_id
